$jsonPath = 'D:\Temp\combat-library-behavior-j75bzt8f\reviews\L01-L03\review.json'
$mdPath = 'D:\Temp\combat-library-behavior-j75bzt8f\reviews\L01-L03\review.md'
$review = [System.IO.File]::ReadAllText($jsonPath) | ConvertFrom-Json
if ($review.cases.Count -ne 3) { throw 'Expected three cases' }
foreach ($case in $review.cases) { foreach ($label in @('A','B')) { if (@('satisfied','partial','not_satisfied','indeterminate') -notcontains $case.answers.$label.overall_status) { throw 'Invalid overall status' } } }
Write-Output 'JSON_VALID: 3 cases, 6 answers, all overall statuses permitted'
foreach ($p in @($jsonPath,$mdPath)) { Write-Output ('ARTIFACT: ' + $p); Write-Output ('SHA256: ' + (Get-FileHash -LiteralPath $p -Algorithm SHA256).Hash); Write-Output ('BYTES: ' + (Get-Item -LiteralPath $p).Length) }
